<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['account'])){$q=$db->prepare('INSERT INTO chart_of_accounts(code,name,type,parent_id) VALUES(?,?,?,NULL)');$q->execute([trim($_POST['code']),trim($_POST['name']),$_POST['type']]);}elseif(isset($_POST['period'])){$q=$db->prepare('INSERT INTO accounting_periods(name,start_date,end_date,status) VALUES(?,?,?,?)');$q->execute([trim($_POST['name']),$_POST['start_date'],$_POST['end_date'],'open']);}}$accounts=$db->query('SELECT * FROM chart_of_accounts WHERE is_active=1 ORDER BY code')->fetchAll();$periods=$db->query('SELECT * FROM accounting_periods ORDER BY start_date DESC')->fetchAll();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Accounting</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-4"><h1 class="h3">Accounting</h1><div class="row g-4"><div class="col-lg-7"><div class="card"><div class="card-body"><h2 class="h5">Chart of Accounts</h2><table class="table"><thead><tr><th>Code</th><th>Name</th><th>Type</th></tr></thead><tbody><?php foreach($accounts as $a):?><tr><td><?=$e($a['code'])?></td><td><?=$e($a['name'])?></td><td><?=$e($a['type'])?></td></tr><?php endforeach;?></tbody></table><form method="post" class="row g-2"><input type="hidden" name="account" value="1"><div class="col-2"><input class="form-control" name="code" placeholder="6000" required></div><div class="col-5"><input class="form-control" name="name" placeholder="Marketing" required></div><div class="col-3"><select class="form-select" name="type"><option>expense</option><option>income</option><option>asset</option><option>liability</option><option>equity</option></select></div><div class="col-2"><button class="btn btn-dark w-100">Add</button></div></form></div></div></div><div class="col-lg-5"><div class="card"><div class="card-body"><h2 class="h5">Accounting Periods</h2><?php foreach($periods as $p):?><div class="border rounded p-2 mb-2"><strong><?=$e($p['name'])?></strong><br><small><?=$e($p['start_date'])?> → <?=$e($p['end_date'])?> · <?=$e($p['status'])?></small></div><?php endforeach;?><form method="post" class="row g-2 mt-2"><input type="hidden" name="period" value="1"><div class="col-12"><input class="form-control" name="name" placeholder="August 2026" required></div><div class="col-6"><input class="form-control" type="date" name="start_date" required></div><div class="col-6"><input class="form-control" type="date" name="end_date" required></div><div class="col-12"><button class="btn btn-dark w-100">Open Period</button></div></form></div></div></div></div></main></body></html>